static int getVal() { return 10; }
public static void main(String[] args) {
  System.out.print(getVal() + 5);
}

static int doubleIt(int n) { return n * 2; }
public static void main(String[] args) {
  System.out.print(doubleIt(4));
}

static void change(int x) { x = 100; }
public static void main(String[] args) {
  int x = 5;
  change(x);
  System.out.print(x);
}

static int sum(int n) {
  if (n <= 1) return 1;
  return n + sum(n - 1);
}
public static void main(String[] args) {
  System.out.print(sum(3));
}

static void f(int a) { System.out.print("i"); }
static void f(double a) { System.out.print("d"); }
public static void main(String[] args) {
  f(5.0);
}
